-- 26-27 학생 명부 전면 리셋(요청: 초등 101 + 중고등 36만 재학생, 나머지는 전부 보관).
-- ① 기존 재학생(active) 전원 보관(inactive) - 유치부 포함, 데이터는 그대로 아카이브.
-- ② 업로드 명부의 초등 101명: 반배정 + 재학 / 중고등 36명: 학년·부서만 + 재학.
-- 매칭: 이름 + 어머니(첫 전화) 뒷8자리. 없으면 새로 삽입(중복 방지). 몇 번 실행해도 결과 동일.
begin;
alter table wr_students drop constraint if exists wr_students_status_check;
alter table wr_students add constraint wr_students_status_check
  check (status in ('active','inactive','보류','졸업','퇴학','전출','전출예정'));

-- ① 전원 보관: 재학(active)만 inactive로. 이미 졸업/전출 등으로 분류된 상태는 그대로 둡니다.
update wr_students set status='inactive' where is_demo=false and status='active';

